class LruCache<K, V>(private val capacity: Int) {
    private class Node<K, V>(val key: K, var value: V) {
        var prev: Node<K, V>? = null
        var next: Node<K, V>? = null
    }

    private val map = HashMap<K, Node<K, V>>()
    private var head: Node<K, V>? = null
    private var tail: Node<K, V>? = null

    fun get(key: K): V? {
        val node = map[key] ?: return null
        moveToTail(node)
        return node.value
    }

    fun put(key: K, value: V) {
        map[key]?.let {
            it.value = value
            moveToTail(it)
            return
        }
        if (map.size == capacity) {
            head?.let { remove(it); map.remove(it.key) }
        }
        val node = Node(key, value)
        append(node)
        map[key] = node
    }

    private fun moveToTail(node: Node<K, V>) {
        if (node === tail) return
        remove(node)
        append(node)
    }

    private fun remove(node: Node<K, V>) {
        val p = node.prev
        val n = node.next
        if (p != null) p.next = n else head = n
        if (n != null) n.prev = p else tail = p
        node.prev = null
        node.next = null
    }

    private fun append(node: Node<K, V>) {
        node.prev = tail
        tail?.next = node
        tail = node
        if (head == null) head = node
    }

    override fun toString(): String {
        val keys = mutableListOf<K>()
        var cur = head
        while (cur != null) { keys += cur.key; cur = cur.next }
        return keys.toString()
    }
}

