suspend fun <T> retry(
    times: Int = 3,
    initialDelayMs: Long = 100,
    maxDelayMs: Long = 1_000,
    factor: Double = 2.0,
    shouldRetry: (Throwable) -> Boolean = { it is IOException },
    block: suspend (attempt: Int) -> T,
): T {
    var delayMs = initialDelayMs
    repeat(times - 1) { attempt ->
        try {
            return block(attempt + 1)
        } catch (e: CancellationException) {
            throw e
        } catch (e: Throwable) {
            if (!shouldRetry(e)) throw e
            println("attempt ${attempt + 1} failed: ${e.message}, waiting ${delayMs}ms")
        }
        delay(delayMs)
        delayMs = (delayMs * factor).toLong().coerceAtMost(maxDelayMs)
    }
    return block(times)
}

fun main() = runBlocking {
    var calls = 0
    val result = retry(times = 4) { attempt ->
        calls++
        if (attempt < 3) throw IOException("timeout")
        "data on attempt $attempt"
    }
    println(result)
    println("calls=$calls")

    try {
        retry { throw IllegalArgumentException("bad request") }
    } catch (e: IllegalArgumentException) {
        println("not retried: ${e.message}")
    }
}

