// 1) Valid parentheses: "({[]})" -> true, "(]" -> false
fun isValid(s: String): Boolean {
    val pairs = mapOf(')' to '(', ']' to '[', '}' to '{')
    val stack = ArrayDeque<Char>()
    for (c in s) {
        when (c) {
            '(', '[', '{' -> stack.addLast(c)
            ')', ']', '}' -> if (stack.removeLastOrNull() != pairs[c]) return false
        }
    }
    return stack.isEmpty()
}

// 2) Two Sum: indices of two numbers adding up to target, O(n)
fun twoSum(nums: IntArray, target: Int): Pair<Int, Int>? {
    val seen = HashMap<Int, Int>()
    nums.forEachIndexed { i, n ->
        seen[target - n]?.let { return it to i }
        seen[n] = i
    }
    return null
}

// 3) First non-repeating character
fun firstUnique(s: String): Char? {
    val counts = s.groupingBy { it }.eachCount()
    return s.firstOrNull { counts[it] == 1 }
}

// 4) Group anagrams
fun groupAnagrams(words: List<String>): List<List<String>> =
    words.groupBy { it.toCharArray().sorted().joinToString("") }.values.toList()

// 5) Reverse the words of a sentence
fun reverseWords(s: String) = s.trim().split(Regex("\\s+")).reversed().joinToString(" ")

// 6) Fibonacci, iterative
fun fib(n: Int): Long {
    var a = 0L
    var b = 1L
    repeat(n) { val t = a + b; a = b; b = t }
    return a
}

fun main() {
    println(listOf("({[]})", "(]", "((", "").map(::isValid))
    println(twoSum(intArrayOf(2, 7, 11, 15), 9))
    println(firstUnique("bazaarb"))
    println(groupAnagrams(listOf("eat", "tea", "tan", "ate", "nat", "bat")))
    println(reverseWords("  hello   cafe bazaar "))
    println((0..10).map(::fib))
    println(fib(90))
}

fun interface Clock { fun now(): Long }

class TtlCache<K, V>(private val ttlMs: Long, private val clock: Clock = Clock { System.currentTimeMillis() }) {
    private data class Entry<V>(val value: V, val expiresAt: Long)
    private val map = HashMap<K, Entry<V>>()

    @Synchronized
    fun get(key: K): V? {
        val e = map[key] ?: return null
        if (clock.now() >= e.expiresAt) {
            map.remove(key)
            return null
        }
        return e.value
    }

    @Synchronized
    fun put(key: K, value: V) {
        map[key] = Entry(value, clock.now() + ttlMs)
    }
}

class FakeClock(var time: Long = 0) : Clock {
    override fun now() = time
}

fun main() {
    val clock = FakeClock()
    val cache = TtlCache<String, String>(ttlMs = 5 * 60_000, clock = clock)
    cache.put("home", "feed-v1")
    println(cache.get("home"))
    clock.time += 4 * 60_000
    println(cache.get("home"))
    clock.time += 60_000
    println(cache.get("home"))
}

