class AppDetailViewModel(
    private val id: String,
    private val repo: AppRepository,
    private val scope: CoroutineScope,
) {
    private val _state = MutableStateFlow<DetailUi>(DetailUi.Loading)
    val state: StateFlow<DetailUi> = _state.asStateFlow()

    private var job: Job? = null

    init { load() }

    fun retry() = load()

    private fun load() {
        job?.cancel()
        job = scope.launch {
            _state.value = DetailUi.Loading
            _state.value = try {
                DetailUi.Success(repo.getApp(id))
            } catch (e: CancellationException) {
                throw e
            } catch (e: Exception) {
                DetailUi.Error(e.message ?: "unknown")
            }
        }
    }
}

